INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-19', 'CashDublo', 'Updated the canonical site navigation to a stationary CashDublo wordmark in a 72px green header with full-bar menu hit area and accessible sliding drawer. Extracted reusable cashdublo-nav.js/css, with Escape/outside close, keyboard focus containment, reduced motion and responsive desktop/tablet/phone layouts.', 'assets/site-navigation.js; assets/site-navigation.css; assets/cashdublo-nav.js; assets/cashdublo-nav.css; NAVIGATION-STANDARD.md; tests/navigation-contract.test.cjs');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-19', 'CashDublo', 'Made the reusable navigation component self-initialize after DOM readiness, while keeping initialization idempotent for the main-site loader.', 'assets/cashdublo-nav.js');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-19', 'CashDublo', 'Made the shared navigation drawer reusable with any id named by aria-controls and allowed app-specific buttons to close the drawer via data-cd-close.', 'assets/cashdublo-nav.js; NAVIGATION-STANDARD.md');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx (AI-01)', 'Contact email replaced site-wide on the President''s order: every CashDublo@gmail.com is now cash.dublo@gmail.com, on the root pages, the app pages, the front-end pages, and the AI version folders. Website icon added: favicon.ico, favicon-32.png, and apple-touch-icon.png at the root and in every AI folder, with the icon links in every page head so the mark loads in the address bar.', 'all pages; all AI folders');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'ChatGPT / AI-02', 'Expanded the shared header interaction so tapping or clicking the CashDublo wordmark also toggles the navigation drawer; the full green header remains a menu hit area, with keyboard activation, focus handling, and the stationary brand preserved. The brand no longer navigates away when tapped; Home remains available in the drawer. Browser/device interaction QA remains required.', 'assets/cashdublo-nav.js; assets/cashdublo-nav.css; NAVIGATION-STANDARD.md; tests/responsive-layout.test.mjs');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx / AI-01', 'The Front Ends page became the link hub on the President''s order: it now opens with The Doors — the live links (the CashDublo Server back end and this Showcase, each with its true state, the built App Store doors named as switching on with the server update) — and carries a new Web Apps section setting up every web app with its true state and repository link (Travel Journal Web dormant, the rest built with no live address yet). PRODUCTION-SITE-PLAN.md added: the President''s decision that production is cashdublo.com built in clean segments, this site staying the hub and workshop, the server update and new layouts being the President''s own round.', 'front-ends.html; PRODUCTION-SITE-PLAN.md');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx / AI-01', 'The theme shelf landed in a new themes/ folder on the President''s order: the theme file standard (themes/README.md) — themes ship as compatible pairs, a .wthm for web faces and an .athm for applications, one core of the 21 color jobs in each — and the six house themes as pairs (Porcelain, Obsidian Gold, Midnight Slate, Goldbone, King, Queen), built from the theme module''s own palette records with every role filled, plus index.json listing the shelf. The hub serves the files directly, so every web face can fetch its .wthm today.', 'themes/README.md; themes/index.json; themes/porcelain.wthm; themes/porcelain.athm; themes/obsidian.wthm; themes/obsidian.athm; themes/slate.wthm; themes/slate.athm; themes/goldbone.wthm; themes/goldbone.athm; themes/king.wthm; themes/king.athm; themes/queen.wthm; themes/queen.athm');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx / AI-01', 'PRODUCTION-SITE-PLAN.md gained the finished-server copy rule on the President''s order: when the production server is finished, a copy of its website is put in a repository called Current Production Server (hyphen form Current-Production-Server on GitHub) as the standing snapshot of the production site as it runs.', 'PRODUCTION-SITE-PLAN.md');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx / AI-01', 'The module package is published on the website, as part of finishing the production server: api/modules.json (all 78 modules as API JSON, the same package the server carries, copied from the verified server package) and api/MODULE-DATA.md now stand on the hub at the same paths the server uses, so the website and the server answer with the same record.', 'api/modules.json; api/MODULE-DATA.md');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'ChatGPT / AI-02', 'Website edition restructure recorded: the 17 AI website editions are gathered under all websites/ as the edition home. The obsolete root-level AI edition folder(s), the website builds/ copy, and the websites/ copies were removed in the final batched cleanup at 8fea7cb03887d27ea98c76d5fd6a4fca79363277. The choosing page now points visitors into all websites/; the README explains which website is the real one and records the cashtheblow.com production servers/ folder; and the midnight website job now follows the consolidated paths. This is a bookkeeping record of the restructure and its follow-up cleanup.', 'all websites/; double click to view all websites.html; README.md (commit befa5c13); cashtheblow.com production servers/; midnight website job; cleanup commit 8fea7cb03887d27ea98c76d5fd6a4fca79363277');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-24', 'Engineering update', 'W6/W7 evidence correction: the website now separates the App Catalog record count (152) from the dated repository inventory count (142), and removes unsupported monetary prices and unapproved free-tier price claims from memberships and website-design pages. The course page''s unsupported annual revenue amount was removed without changing the surrounding teaching content. No checkout or commercial terms are implied; the App Catalog has no approved price values.', 'index.html; repositories.html; memberships.html; website-design.html; course.html');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-24', 'Engineering update', 'W6 follow-up correction: replaced the stale 142 repository snapshot with the latest 146-repository fleet-sweep count recorded in the current AI2AISync handoff. Kept the 152 App Catalog record count separate and documented that repository counts vary by inventory script. The 146 figure is labeled with its November 24 source date.', 'repositories.html; CHANGES.md');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-24', 'ChatGPT / AI-02', 'Added a separate corporate umbrella website prototype under corporate/: parent-company landing page plus four distinct business-division websites (CashDublo Digital, CashDublo Learning, CashDublo Studio, Get Cash Platform), shared responsive CSS and accessible mobile navigation, and architecture/acceptance documentation. Existing root site remains unchanged. Cash Flow is presented as a proposed umbrella brand; divisions are not represented as legally formed subsidiaries. Feature branch only; no merge or deployment.', 'corporate/index.html; corporate/digital/index.html; corporate/learning/index.html; corporate/studio/index.html; corporate/get-cash/index.html; corporate/assets/corporate.css; corporate/assets/corporate.js; corporate/ARCHITECTURE.md; corporate/README.md');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-25', 'Onyx / AI-01', 'The website takes the theme (website queue W19, the President''s order 2026-11-25 04:06): the site generator (make_platform_pages.py) now carries the SUNLIGHT block — the themes module sunlight gradient (GRADIENTS.md) at the one house angle (135deg), stops derived from the site palette, AA checked across every stop — and injects it into every page it builds or patches; privacy takes a dark variant derived from its own palette. The standing pages were themed with the identical block: 62 pages — the generator family (index, apps, the five platform pages, privacy), the front-ends overview and its five pages, the remaining root pages on the house palette, and the 34 per-app pages under apps/. Named not-upgradable in this round: the corporate/ site (its own design system and external CSS), the per-AI folders under all websites/ (each its own design), and the retired v2 navigation assets. No page content changed: each themed page differs from its pinned predecessor only by the added block.', 'make_platform_pages.py; CHANGES.md; CHANGES.sql; index.html; apps.html; android.html; iphone.html; mac.html; windows.html; linux.html; privacy.html; front-ends.html; front-ends/; repositories.html; memberships.html; course.html; news.html; code.html; games.html; back-ends.html; website-design.html; cashdublo-app-store.html; login.html; terminal.html; rss.html; 404.html; products.html; apps/');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-27', 'Onyx / AI-01', 'The App Store page becomes the web store (the President''s order 2026-11-27 21:30): cashdublo-app-store.html is rebuilt as the working web face of the CashDublo App Store — the store app''s shelves carried to the web in the house theme. The storefront carries a search box, kind and platform browsing, and one listing card per App Catalog row with a display name — 155 listings — each card showing the name, version, description, platform marks, the price terms exactly as the catalog states them (a free trial, free with ads, or price TBA where the catalog sets none), and the app''s status. Every listing links to its own store page, store/app.html?app=<slug>, with the full description and its Get panel. Listings are driven by store/apps-data.js, generated from the App Catalog export by the new scripts/build-store-data.mjs, so the catalog stays the single source; store/README.md records how the store fits together and how the data file is rebuilt. The purchase path is wired honestly to the production server''s store doors (the shelf door /api/store/catalog, the package door, the ledger door): apps whose status is Builds and stable or Live carry a Get action to the shelf door, and both the storefront and each Get panel state plainly that the server shelf stands empty today, so no purchase completes until an app lands on the shelf; apps still in build, in design or at spec stage show their status instead of a Get action. iOS listings carry the store SPEC''s honest-limits note (TestFlight and the EU alternative marketplaces for server editions). The old page''s information stands consolidated complete at the bottom of the storefront: what the platform provides, product-specific pricing, security and customer protections, and availability — nothing it said is lost. The page keeps the standard navigation and the SUNLIGHT theme block.', 'cashdublo-app-store.html; store/app.html; store/apps-data.js; store/README.md; scripts/build-store-data.mjs; CHANGES.md; CHANGES.sql');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-27', 'Onyx / AI-01', 'All applications as a card stack (the President''s order 2026-11-27 21:42): new store page store/cards.html carries all 155 catalogue listings as cards loaded one over the other in a single stack — phone first, full-width cards, vertical scroll with snap moving one card at a time, each card settling in front with the passed cards peeking at the top edge; on wide screens the stack stands centered at card width, never a grid. Each card carries the same facts as its shelf card (name, version, description, platform marks, price terms or status as the catalog states them) and tapping a card opens its store page, store/app.html?app=<slug>. The stack reads the one data file store/apps-data.js and carries no data of its own. Entries wired: the storefront cashdublo-app-store.html gains a Browse all as cards link beside its listing count, and apps.html gains the matching link in its hero, so the all-applications click lands on the stack from either door; the stack page links back to the storefront shelf (the grid). store/README.md records the new piece. Standard navigation and the SUNLIGHT theme block kept; no other page''s behavior changes.', 'store/cards.html; cashdublo-app-store.html; apps.html; store/README.md; CHANGES.md; CHANGES.sql');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-28', 'Onyx / AI-01', 'Customer sign-in on the website (the President''s order 2026-11-28: implement the Google and Apple sign-ins for the website — the site only, not the apps): the customer login page login.html already stood with its doors wired to the server''s /api/auth-config configuration door and its honest dormant state; this round finishes the website side. The Google and Apple buttons are now drawn to each provider''s published button rules — Google: white button, the four-color G mark, “Continue with Google”; Apple: black button, the Apple mark, “Continue with Apple” — each standing full width above the GitHub and Microsoft doors, which keep their standing shape; the buttons stay disabled until the configuration door answers switched on, and the page keeps its dormant wording while it does not. The storefront cashdublo-app-store.html gains the account line in its hero: a Sign in link to the login page while signed out or dormant, and — once sign-in is switched on and a session stands — the signed-in name as the provider gave it, with a Sign out control. It reads the same /api/auth-config door and loads the sign-in library only when that door answers configured, so a dormant storefront makes no new outside calls. store/README.md records the sign-in piece. On the server side (its own repo, same round) the configuration door learned the public website face''s origin, so the login page can read its configuration from the public site at all. No other page''s behavior changes.', 'login.html; cashdublo-app-store.html; store/README.md; CHANGES.md; CHANGES.sql');
INSERT INTO changes (id, date, who, what, docs) VALUES (33, '2026-11-28', 'AI-01', 'App detail screen rebuilt: everything about the app on one screen — full description, tagline, whats new, price and Get doors — with the app layouts as a carousel (one at a time on a phone, three side by side with arrows on larger screens); apps with no renderings show no carousel', 'store/app.html');
INSERT INTO changes (id, date, who, what, docs) VALUES (34, '2026-11-28', 'AI-01', 'The Muse folder page (all websites/muse) now carries the full registry: all 161 apps as cards generated from the App Catalog — icon, name, tagline, full description, category and subcategories, platforms and families, form factors, version, status, the price line exactly as the catalog states it, and a link to each app''s store page — with a search box and Platform and Type selector bars over the shelf. The apps that carry layout renderings in the record show them on their cards; no other card shows any. New generator scripts/build-muse-data.mjs builds the folder''s registry-data.js from the catalog export and its site-photos record, so the page can be rebuilt whenever the registry is refreshed. The folder''s own design, and its Featured and Marketplace sections, stand as they were.', 'all websites/muse/index.html; all websites/muse/registry-data.js; scripts/build-muse-data.mjs; CHANGES.md; CHANGES.sql');
INSERT INTO changes (id, date, who, what, docs) VALUES (35, '2026-11-28', 'AI-01', 'The Muse folder page''s top is black and gold, and the umbrella stands at the top again (the President''s orders 2026-11-28 18:33-18:34). The shared navigation script was removing the page''s own header — the gold umbrella, title, strapline and the "One builder, one umbrella" line — and painting its bars teal green and cream; the page''s header is now a hero block the shared script does not remove, and two page-local files in the Muse folder (gold-top.css, gold-top.js) restyle the shared bars, buttons, drawer and quick bar in the folder''s black and gold and point every top link at a black-and-gold version under all websites/muse/gold/. Those versions — 21 pages: the content pages keep their own content rewrapped in black and gold, and the generated lists (All Apps, the five platform pages, Front Ends, Games) are drawn from the same registry data as the page''s own shelf — are built by the new generator scripts/build-muse-gold.mjs. The original pages and every shared file stand untouched, and the other layout copies keep their own look.', 'all websites/muse/index.html; all websites/muse/gold-top.css; all websites/muse/gold-top.js; all websites/muse/gold/ (21 pages, gold.css, gold-render.js); scripts/build-muse-gold.mjs; CHANGES.md; CHANGES.sql');
INSERT INTO changes (id, date, who, what, docs) VALUES (36, '2026-11-28', 'AI-01', 'The Grok folder page (all websites/Grok) now carries the full registry — the same treatment the Muse folder page received (the President''s order 2026-11-28 18:42) — in the Grok folder''s own design (near-black, cyan accent): all 161 apps as cards generated from the App Catalog — icon, name, tagline, full description, category and subcategories, platforms and families, form factors, version, status, the price line exactly as the catalog states it, and a link to each app''s store page — with a search box and Platform and Type selector bars over the shelf. The apps that carry layout renderings in the record show them on their cards; no other card shows any. The apple2player renderings set attaches to neither catalog row (the catalog carries that app as apple2player-mac and apple2player-win) — the standing record gap, named, not guessed. New generator scripts/build-grok-data.mjs builds the folder''s registry-data.js from the catalog export and its site-photos record, so the page can be rebuilt whenever the registry is refreshed. The folder''s own sections and design stand as they were. Its top needed no restyle: this page never loaded the shared site navigation, so no shared bars stand on it — its own header already stands at its top in its own palette, and no shared file was touched. A page-local script (grok-top.js) points the page''s top links — the header brand and nav, the hero buttons, the footer row — at Grok-design versions of their target pages under all websites/Grok/edition/: Home and Privacy keep their own content rewrapped in this folder''s design with the shared navigation stripped, and All Apps and Front Ends are drawn from the same registry data as the page''s own shelf. Those versions are built by the new generator scripts/build-grok-edition.mjs. The original pages stand untouched, and the other layout copies keep their own look.', 'all websites/Grok/index.html; all websites/Grok/registry-data.js; all websites/Grok/grok-top.js; all websites/Grok/edition/ (4 pages, edition.css, edition-render.js); scripts/build-grok-data.mjs; scripts/build-grok-edition.mjs; CHANGES.md; CHANGES.sql');
INSERT INTO changes (id, date, who, what, docs) VALUES (37, '2026-11-28', 'AI-01', 'The Grok folder page''s menu now wears the page''s own colors in every state, and its navigation no longer switches domains (the President''s order 2026-11-28 18:52). In all websites/Grok/index.html, an explicit navigation color block pins the menu to the page''s own palette - resting items in the text tone (#fafafa) and muted (#a1a1aa), hover and focus in the cyan accent (#22d3ee), the pressed state in the purple accent (#a78bfa) - with visited-state rules for the brand, the header nav, the hero buttons, the cards and the footer row, so no browser default link blue or visited purple can show in the navigation; the footer links now rest in muted and take the accent on hover, like the rest of the menu. The menu items whose destination already lives on this page now flow to it in-page instead of leaving for another page: All Apps in the header nav, the hero''s Explore every app button, the Featured section''s See the complete collection button and the footer''s All apps link all point at the page''s own Full Shelf registry section (#registry), beside the standing in-page items (About to #about, Apps to #featured). The registry cards'' View in the store links - and the same links on the folder''s edition list pages (edition/edition-render.js) - are now relative (store/app.html?app=<slug> against the site root) instead of the catalog data''s absolute pages.dev addresses, so following one keeps the visitor on the face they are already on; the destination is unchanged. The edition versions of Home, Front Ends and Privacy stand as built and remain linked by relative links only. No shared file was touched, and the other layout copies keep their own look.', 'all websites/Grok/index.html; all websites/Grok/edition/edition-render.js; CHANGES.md; CHANGES.sql');
INSERT INTO changes (id, date, who, what, docs) VALUES (38, '2026-11-28', 'AI-01', 'A new folder website stands in the folder system: CashDublo One (all websites/CashDublo One/) — the main CashDublo website turned into another website within the folder system, on the President''s order (2026-11-28 18:57: take the website served at cashdublo.vercel.app and turn it into another website in a folder named CashDublo One). The folder carries a self-contained copy of the main website as it stands at db9627c9: 81 files — the 24 pages that stand at the root (the front page, All Apps, the five platform pages, the App Store, Courses, Front Ends, Back Ends, Games, My Source Code, Memberships, Newsletter, Products, Repositories, RSS Feeds, Command Tools, Website Design, Log in, Privacy, the 404 page and the view-all-websites page), the store''s three files (the detail page, the card stack and the store data file), the five front-ends pages, the 39 per-app pages under apps/, the four shared navigation files under assets/, the four feed files, site.js and versions.json. The design is the main website''s own, unchanged — no other folder''s look was imported, and the copy''s title and branding read as the main site''s. Every internal link was rewritten folder-relative, so the copy browses as its own website inside the folder: links between the copied pages stay inside the folder; the shared navigation script finds its root from its own address, so its menus open the folder''s pages; the store pages'' script-built icon paths were rebased the same way; and references to what lives only at the root — the app icon and photo images and the favicon files, which are pictures and cannot ride this push — point back to the root copies by relative path, so following any link stays on the same face and never switches domains. The store data file is the same current data from the same source, copied as it stands; no number was hand-edited. The original root pages stand untouched — site copies are never deleted, only unused (the President''s standing rule).', 'all websites/CashDublo One/ (81 files: 24 root pages; store/app.html, store/cards.html, store/apps-data.js; front-ends/ 5 pages; apps/ 39 pages; assets/ 4 files; feeds/ 4 files; site.js; versions.json); CHANGES.md; CHANGES.sql');
